#include <cmath>
#include <iostream>
using namespace std;

int find_gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    int num1, num2, max_den;
    cin >> num1 >> num2 >> max_den;
    int g = find_gcd(num1, num2);
    num1 /= g;
    num2 /= g;
    if (max_den >= num2) {
        cout << num1 << "/" << num2 << "\n";
    } else {
        long double ratio = (long double)num1 / num2;
        long double closest_diff = ratio;
        int numerator = 0, denominator = 1;
        for (int i = 1; i <= max_den; ++i) {
            long double candidate = i * ratio;
            long double lower = floor(candidate);
            long double diff_lower = abs(lower / i - ratio);
            long double diff_upper = abs((lower + 1) / i - ratio);
            if (closest_diff > diff_lower || closest_diff > diff_upper) {
                if (diff_lower > diff_upper) {
                    numerator = lower + 1;
                } else {
                    numerator = lower;
                }
                denominator = i;
                closest_diff = min(diff_lower, diff_upper);
            }
        }
        cout << numerator << "/" << denominator;
    }
    return 0;
}
